                    "sql": "CREATE OR REPLACE TABLE maplemonk.Inventory_Data_Base_amazon_vc AS SELECT * FROM ( select \'AMAZON VC CORE BISS CRPL\' as Source, \'AMAZON VC CORE BISS CRPL\' as location, cast(null as string) as Brand, cast(startDate as date) DATA_FETCH_DATE, a.asin, REPLACE(upper(b.master_sku), \'\\'\', \'\') AS SKU, upper(b.product_title) as PRODUCTNAME, CONCAT(UPPER(TRIM(b.CATEGORY)), \' \', UPPER(TRIM(b.SUB_CATEGORY))) AS master_category, cast(null as int64) as reserved, cast(sellableOnHandInventoryUnits as int64) AVAILABLEINVENTORY, null as In_Transit, cast(null as string) as Undispatched_Unassigned_Quantity from `maplemonk.Buildskill_Amazon_VC_Core_Biss_CRPL_GET_VENDOR_INVENTORY_REPORT` a left join (select * from (select asin, Master_SKU, PRODUCT_TITLE, Category, Sub_Category, row_number() over (partition by replace(Master_SKU,\' \',\'\') order by 1) rw from `maplemonk.Buildskill_GS_SKU_MASTER`) where rw = 1) b on trim(a.asin) = trim(b.asin) qualify row_number() over (partition by a.asin, cast(_airbyte_normalized_at as date), startDate order by cast(_airbyte_normalized_at as date) desc) = 1 UNION ALL select \'AMAZON VC CORE CHILD CRPL\' as Source, \'AMAZON VC CORE CHILD CRPL\' as location, cast(null as string) as Brand, cast(startDate as date) DATA_FETCH_DATE, a.asin, REPLACE(upper(b.master_sku), \'\\'\', \'\') AS SKU, upper(b.product_title) as PRODUCTNAME, CONCAT(UPPER(TRIM(b.CATEGORY)), \' \', UPPER(TRIM(b.SUB_CATEGORY))) AS master_category, cast(null as int64) as reserved, cast(sellableOnHandInventoryUnits as int64) AVAILABLEINVENTORY, null as In_Transit, cast(null as string) as Undispatched_Unassigned_Quantity from `maplemonk.Buildskill_Amazon_VC_Core_Child_CRPL_GET_VENDOR_INVENTORY_REPORT` a left join (select * from (select asin, Master_SKU, PRODUCT_TITLE, Category, Sub_Category, row_number() over (partition by replace(Master_SKU,\' \',\'\') order by 1) rw from `maplemonk.Buildskill_GS_SKU_MASTER`) where rw = 1) b on trim(a.asin) = trim(b.asin) qualify row_number() over (partition by a.asin, cast(_airbyte_normalized_at as date), startDate order by cast(_airbyte_normalized_at as date) desc) = 1 UNION ALL select \'AMAZON VC CORE CRPL\' as Source, \'AMAZON VC CORE CRPL\' as location, cast(null as string) as Brand, cast(startDate as date) DATA_FETCH_DATE, a.asin, REPLACE(upper(b.master_sku), \'\\'\', \'\') AS SKU, upper(b.product_title) as PRODUCTNAME, CONCAT(UPPER(TRIM(b.CATEGORY)), \' \', UPPER(TRIM(b.SUB_CATEGORY))) AS master_category, cast(null as int64) as reserved, cast(sellableOnHandInventoryUnits as int64) AVAILABLEINVENTORY, null as In_Transit, cast(null as string) as Undispatched_Unassigned_Quantity from `maplemonk.Buildskill_Amazon_VC_Core_CRPL_GET_VENDOR_INVENTORY_REPORT` a left join (select * from (select asin, Master_SKU, PRODUCT_TITLE, Category, Sub_Category, row_number() over (partition by replace(Master_SKU,\' \',\'\') order by 1) rw from `maplemonk.Buildskill_GS_SKU_MASTER`) where rw = 1) b on trim(a.asin) = trim(b.asin) qualify row_number() over (partition by a.asin, cast(_airbyte_normalized_at as date), startDate order by cast(_airbyte_normalized_at as date) desc) = 1 UNION ALL select \'AMAZON VC CRPL DEL\' as Source, \'AMAZON VC CRPL DEL\' as location, cast(null as string) as Brand, cast(startDate as date) DATA_FETCH_DATE, a.asin, REPLACE(upper(b.master_sku), \'\\'\', \'\') AS SKU, upper(b.product_title) as PRODUCTNAME, CONCAT(UPPER(TRIM(b.CATEGORY)), \' \', UPPER(TRIM(b.SUB_CATEGORY))) AS master_category, cast(null as int64) as reserved, cast(sellableOnHandInventoryUnits as int64) AVAILABLEINVENTORY, null as In_Transit, cast(null as string) as Undispatched_Unassigned_Quantity from `maplemonk.Buildskill_Amazon_VC_CRPL_DEL_GET_VENDOR_INVENTORY_REPORT` a left join (select * from (select asin, Master_SKU, PRODUCT_TITLE, Category, Sub_Category, row_number() over (partition by replace(Master_SKU,\' \',\'\') order by 1) rw from `maplemonk.Buildskill_GS_SKU_MASTER`) where rw = 1) b on trim(a.asin) = trim(b.asin) qualify row_number() over (partition by a.asin, cast(_airbyte_normalized_at as date), startDate order by cast(_airbyte_normalized_at as date) desc) = 1 UNION ALL select \'AMAZON VC HI KA CRPL\' as Source, \'AMAZON VC HI KA CRPL\' as location, cast(null as string) as Brand, cast(startDate as date) DATA_FETCH_DATE, a.asin, REPLACE(upper(b.master_sku), \'\\'\', \'\') AS SKU, upper(b.product_title) as PRODUCTNAME, CONCAT(UPPER(TRIM(b.CATEGORY)), \' \', UPPER(TRIM(b.SUB_CATEGORY))) AS master_category, cast(null as int64) as reserved, cast(sellableOnHandInventoryUnits as int64) AVAILABLEINVENTORY, null as In_Transit, cast(null as string) as Undispatched_Unassigned_Quantity from `maplemonk.Buildskill_Amazon_VC_HI_KA_CRPL_GET_VENDOR_INVENTORY_REPORT` a left join (select * from (select asin, Master_SKU, PRODUCT_TITLE, Category, Sub_Category, row_number() over (partition by replace(Master_SKU,\' \',\'\') order by 1) rw from `maplemonk.Buildskill_GS_SKU_MASTER`) where rw = 1) b on trim(a.asin) = trim(b.asin) qualify row_number() over (partition by a.asin, cast(_airbyte_normalized_at as date), startDate order by cast(_airbyte_normalized_at as date) desc) = 1) QUALIFY ROW_NUMBER() OVER (PARTITION BY asin, DATA_FETCH_DATE ORDER BY AVAILABLEINVENTORY DESC, Source) = 1 ; CREATE OR REPLACE TABLE maplemonk.All_SKU_Dates_amazon_vc AS SELECT DISTINCT c.date_day, d.Source, d.asin, d.PRODUCTNAME, d.master_category, d.location FROM maplemonk.Inventory_Data_Base_amazon_vc AS d CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE_TRUNC(CURRENT_DATE(), YEAR), CURRENT_DATE())) AS date_day ) AS c ; CREATE OR REPLACE TABLE maplemonk.Inventory_Data_amazon_vc AS SELECT cast(d.DATE_DAY as date) DATA_FETCH_DATE, d.asin, d.productname, d.master_category, ifnull(sum(case when lower(d.source) like \'%amazon vc%\' then ifnull(i.Availableinventory,0) else 0 end),0) Amazon_IN_Inventory, FROM maplemonk.All_SKU_Dates_amazon_vc d LEFT JOIN maplemonk.Inventory_Data_Base_amazon_vc i ON lower(d.asin) = lower(i.asin) and date(d.date_day) = date(i.Data_Fetch_Date) and d.location = i.location and d.source = i.source GROUP BY 1,2,3,4 ; CREATE OR REPLACE TABLE maplemonk.Sales_Data_Daily_amazon_vc AS SELECT TRIM(asin) AS asin, DATE(sales_date) + 1 AS order_date, SUM(IFNULL(Ordered_Revenue,0)) AS selling_price, SUM(IFNULL(ordered_units,0)) AS quantity FROM `maplemonk.Buildskill_S3_Amazon_Daily_Sales_Report_Final` where cast(sales_date as date) < (select max(DATA_FETCH_DATE) from maplemonk.Inventory_Data_amazon_vc) GROUP BY 1,2 ; CREATE OR REPLACE TABLE maplemonk.Sales_35avg_w_Inv_amazon_vc AS SELECT ID.DATA_FETCH_DATE, ID.asin, UPPER(ID.PRODUCTNAME) AS Product_Final_Name, MAX(IFNULL(ID.Amazon_IN_Inventory,0)) AS Amazon_IN_Inventory, MAX(IFNULL(SD35.weekly_units,0)) AS Max_weekly_units, MIN(IFNULL(SD35.weekly_units,0)) AS Min_weekly_units FROM maplemonk.Inventory_Data_amazon_vc ID LEFT JOIN ( SELECT asin, ORDER_DATE, SUM(quantity) OVER ( PARTITION BY asin ORDER BY ORDER_DATE ROWS BETWEEN 6 PRECEDING AND CURRENT ROW ) AS Weekly_Units FROM maplemonk.Sales_Data_Daily_amazon_vc ) SD35 ON ID.asin = SD35.asin AND DATE_DIFF(ID.DATA_FETCH_DATE, SD35.ORDER_DATE, DAY) BETWEEN 0 AND 35 GROUP BY 1,2,3; CREATE OR REPLACE TABLE maplemonk.INVENTORY_FINAL_amazon_vc AS SELECT coalesce(SD35.DATA_FETCH_DATE,SD1.Order_Date) DATA_FETCH_DATE, coalesce(SD35.asin, SD1.asin) asin, coalesce(SD35.Product_Final_Name) Product_Final_Name, Amazon_IN_Inventory, Max_weekly_units, Min_weekly_units, SUM(IFNULL(SD1.QUANTITY, 0)) AS Sold_Quantity_last_day, SUM(IFNULL(SD1.SELLING_PRICE, 0)) AS Selling_Price_last_day FROM maplemonk.Sales_35avg_w_Inv_amazon_vc SD35 FULL OUTER JOIN maplemonk.Sales_Data_Daily_amazon_vc SD1 ON SD35.asin = SD1.asin AND DATE_DIFF(SD35.DATA_FETCH_DATE, SD1.ORDER_DATE, DAY) = 1 GROUP BY 1, 2, 3, 4, 5, 6; CREATE OR REPLACE TABLE MAPLEMONK.Buildskill_INVENTORY_FACT_ITEMS_amazon_vc AS SELECT IFT.DATA_FETCH_DATE ,IFT.asin ,IFT.Product_Final_Name product_name_final ,MC.master_category ,IFT.Amazon_IN_Inventory ,IFT.Max_weekly_units ,IFT.Min_weekly_units ,IFT.Sold_Quantity_last_day ,IFT.Selling_Price_last_day FROM maplemonk.INVENTORY_FINAL_amazon_vc IFT LEFT JOIN (SELECT DISTINCT asin, master_category FROM maplemonk.Inventory_Data_amazon_vc) MC ON IFT.asin = MC.asin ;",
                    "transaction": true
                }
            ) }}
